/** @param {NS} ns */
export async function main(ns) {
  const ports = ['BruteSSH.exe', 'FTPCrack.exe', 'RelaySMTP.exe', 'HTTPWorm.exe', 'SQLInject.exe'];
  const openPort = (server, port) => {
    if (port === 'BruteSSH.exe' && ns.fileExists(port, 'home')) ns.brutessh(server);
    else if (port === 'FTPCrack.exe' && ns.fileExists(port, 'home')) ns.ftpcrack(server);
    else if (port === 'RelaySMTP.exe' && ns.fileExists(port, 'home')) ns.relaysmtp(server);
    else if (port === 'HTTPWorm.exe' && ns.fileExists(port, 'home')) ns.httpworm(server);
    else if (port === 'SQLInject.exe' && ns.fileExists(port, 'home')) ns.sqlinject(server);
  };

  const getReachable = (start) => {
    let visited = new Set([start]);
    let queue = [start];
    while (queue.length > 0) {
      let curr = queue.shift();
      let neighbors = ns.scan(curr);
      for (let n of neighbors) {
        if (!visited.has(n)) {
          visited.add(n);
          queue.push(n);
        }
      }
    }
    return Array.from(visited);
  };

  let servers = getReachable('home');
  for (let server of servers) {
    if (server === 'home') continue;
    if (ns.hasRootAccess(server)) continue;
    let portsNeeded = ns.getServerNumPortsRequired(server);
    for (let port of ports) openPort(server, port);
    if (ns.getServerNumPortsRequired(server) <= ports.filter(p => ns.fileExists(p, 'home')).length) {
      ns.nuke(server);
    }
  }

  let target = null, maxProfit = 0;
  for (let server of servers) {
    if (server === 'home' || !ns.hasRootAccess(server)) continue;
    if (ns.getServerRequiredHackingLevel(server) > ns.getHackingLevel()) continue;
    let money = ns.getServerMaxMoney(server);
    let sec = ns.getServerSecurityLevel(server);
    let profit = money / (1 + sec);
    if (profit > maxProfit) {
      maxProfit = profit;
      target = server;
    }
  }

  if (!target) target = 'n00dles';

  while (true) {
    let sec = ns.getServerSecurityLevel(target);
    let minSec = ns.getServerMinSecurityLevel(target);
    let money = ns.getServerMoneyAvailable(target);
    let maxMoney = ns.getServerMaxMoney(target);

    if (sec > minSec + 5) {
      await ns.weaken(target);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const servers = new Set(['home']);
  const queue = ['home'];
  while (queue.length > 0) {
    const s = queue.shift();
    const neighbors = ns.scan(s);
    for (const n of neighbors) {
      if (!servers.has(n)) {
        servers.add(n);
        queue.push(n);
      }
    }
  }
  for (const s of servers) {
    try { ns.brutessh(s); } catch (e) {}
    try { ns.ftpcrack(s); } catch (e) {}
    try { ns.relaysmtp(s); } catch (e) {}
    try { ns.httpworm(s); } catch (e) {}
    try { ns.sqlinject(s); } catch (e) {}
    try { ns.nuke(s); } catch (e) {}
  }
  let target = 'n00dles';
  while (true) {
    const sec = ns.getServerSecurityLevel(target);
    const minSec = ns.getServerMinSecurityLevel(target);
    const money = ns.getServerMoneyAvailable(target);
    const maxMoney = ns.getServerMaxMoney(target);
    if (sec > minSec + 5) {
      await ns.weaken(target);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
  }
}

