/** @param {NS} ns */
export async function main(ns) {
  const hosts = [];
  const queue = ['home'];
  while (queue.length) {
    const curr = queue.shift();
    if (hosts.includes(curr)) continue;
    hosts.push(curr);
    const children = ns.scan(curr);
    for (const child of children) {
      if (!hosts.includes(child)) queue.push(child);
    }
  }

  for (const host of hosts) {
    if (ns.hasRootAccess(host)) continue;
    const ports = ns.getServerNumPortsRequired(host);
    if (ports <= 0) { ns.nuke(host); continue; }
    try { ns.brutessh(host); } catch(e) {}
    try { ns.ftpcrack(host); } catch(e) {}
    if (ports <= 2) { ns.nuke(host); }
  }

  while (true) {
    let best = null, bestMoney = 0;
    for (const host of hosts) {
      if (!ns.hasRootAccess(host)) continue;
      const reqHack = ns.getServerRequiredHackingLevel(host);
      if (reqHack > ns.getHackingLevel()) continue;
      const max = ns.getServerMaxMoney(host);
      if (max > bestMoney) { best = host; bestMoney = max; }
    }
    if (!best) { await ns.sleep(1000); continue; }
    const security = ns.getServerSecurityLevel(best);
    const minSec = ns.getServerMinSecurityLevel(best);
    if (security > minSec) {
      await ns.weaken(best);
    } else {
      const money = ns.getServerMoneyAvailable(best);
      const max = ns.getServerMaxMoney(best);
      if (money < max * 0.5) {
        await ns.grow(best);
      } else {
        await ns.hack(best);
      }
    }
  }
}

